import{_ as i,C as t,o,c as r,a6 as e,E as n}from"./chunks/framework.B_q3ZJNF.js";const m=JSON.parse('{"title":"K线：一根蜡烛里的多空战争","description":"","frontmatter":{"title":"K线：一根蜡烛里的多空战争"},"headers":[],"relativePath":"astock-course/04-k-line.md","filePath":"astock-course/docs/04-k-line.md"}'),s={name:"astock-course/04-k-line.md"};function h(p,a,D,d,c,u){const l=t("KLineChart");return o(),r("div",null,[a[0]||(a[0]=e('<h1 id="k线-一根蜡烛里的多空战争" tabindex="-1">K线：一根蜡烛里的多空战争 <a class="header-anchor" href="#k线-一根蜡烛里的多空战争" aria-label="Permalink to &quot;K线：一根蜡烛里的多空战争&quot;">​</a></h1><p>打开任何一个行情软件，点开一只股票，扑面而来的都是红红绿绿的小蜡烛：有的胖成一截短柱，有的头顶拖着长尾巴，底下一排高矮不齐的量柱跟着起哄。这个画面你多半见过，却未必拆开看过。这一章就把一根蜡烛拆到零件：它记下的是一天之内买方与卖方的攻防，而攻防的激烈程度写在底下的量柱里。</p><p>先讲一段行情。下面要用的是课程自产的合成剧情（D1 到 D60 共 60 个交易日，与任何真实个股无关），剧情中段有第 36、37 两根几乎一模一样的蜡烛：一根实体 0.43 元、当天上涨 4.67%；另一根实体 0.44 元、当天上涨 4.65%。可它们脚下的量柱差着十倍——前者 27.9 万手，接近平日（中位数约 7.2 万手）的四倍；后者只有 2.7 万手，不到平日的四成（手是计量的单位，1 手 = 100 股，下文细说）。同样一根大阳线，前一天放量、这一天缩量，背后是两种完全相反的故事。这一章教你把故事读出来，并在本章末尾亲手揭晓藏在图里的后 20 根，看看哪种故事在剧情里应验。</p><h2 id="工具箱" tabindex="-1">工具箱 <a class="header-anchor" href="#工具箱" aria-label="Permalink to &quot;工具箱&quot;">​</a></h2><p>本章调用一批旧积木，分三组。读行情规则的三条：集合竞价——把一段时间内的买卖申报集中进同一个池子，按最大成交量原则一次性撮合出唯一成交价，开盘价与收盘价都由它产生（第 3 章）；涨跌停板——以前收盘价为基准限制当日报价的最大波动幅度，主板 ±10%（第 3 章）；T+1——当日买入的股票，次一交易日才能卖出（第 3 章）。算钱的五条：货币时间价值——跨期比较前先折到同一时点（第 1 章）；收益率——（期末 − 期初）÷ 期初（第 1 章）；通货膨胀——比较不同年份的钱先换算成同一年份的购买力（第 1 章）；实际购买力——实际收益率 ≈ 名义收益率 − 通胀率（第 1 章）；股权——对公司资产与利润的剩余索取权（第 2 章）。称公司分量的三条：市值——股价 × 总股本（第 2 章）；盈利——公司一段时期赚到的净利润（第 2 章）；估值——价格相对基本面的倍数关系（第 2 章）。手边有这十一条，本章每一根蜡烛都能对上规则与账本。</p><h2 id="原理-一天的交易-怎么浓缩成一根蜡烛" tabindex="-1">原理：一天的交易，怎么浓缩成一根蜡烛 <a class="header-anchor" href="#原理-一天的交易-怎么浓缩成一根蜡烛" aria-label="Permalink to &quot;原理：一天的交易，怎么浓缩成一根蜡烛&quot;">​</a></h2><h3 id="四个价格-从撮合时间线里长出来" tabindex="-1">四个价格：从撮合时间线里长出来 <a class="header-anchor" href="#四个价格-从撮合时间线里长出来" aria-label="Permalink to &quot;四个价格：从撮合时间线里长出来&quot;">​</a></h3><p>先推四个价格的来历。开盘价由你工具箱里的集合竞价定出：9:15 到 9:25 全场申报进池子，9:25 一次性撮合出当天的第一笔价（第 3 章）。9:30 之后进入连续竞价——买卖申报随到随撮、价格逐笔产生的撮合方式（第 3 章）——买方与卖方全天拉锯，把最高价、最低价一笔一笔打出来；临近收盘，14:57 到 15:00 再进一次集合竞价的池子，撮出收盘价。一天结束，行情记录只保留四个数：开盘价、收盘价、最高价、最低价。不是记录偷懒，而是这四个数恰好钉住了全天的关键节点：起跑线（开盘）、终局（收盘）、到过的顶点（最高）、踩过的深谷（最低）。</p><p>K线——用一根蜡烛把一个周期的四个价格画成图，本章周期就是一个交易日：开与收之间画成矩形，叫实体；从实体向上、向下延伸到最高价与最低价的细线，叫影线。为什么非要一套专门的画法？反过来想：假如一天只留一个收盘价，你知道终局，却不知道这一天价格曾冲得多高、跌得多深，盘中那场攻防会整个蒸发。四个价格加一套画法，把一天的战斗压进一张图。四个数也不是孤立的，摆回时间线就能看出分工：开盘集合竞价定下开盘，连续竞价的多空拉锯跑出最高与最低，收盘集合竞价再定收盘——一根蜡烛的四价，就是这条撮合时间线上的四个落点。顺带对齐一把旧尺子：四个价是同一天的钱，不必折算；一旦跨天比价，货币时间价值就要拿回来用——不同时点的钱先折到同一点再比较（第 1 章）。</p><h3 id="阳线与阴线-谁赢下了这一天" tabindex="-1">阳线与阴线：谁赢下了这一天 <a class="header-anchor" href="#阳线与阴线-谁赢下了这一天" aria-label="Permalink to &quot;阳线与阴线：谁赢下了这一天&quot;">​</a></h3><p>阳线与阴线——收盘价高于开盘价叫阳线，低于开盘价叫阴线；A 股行情惯例把阳线画成红色、阴线画成绿色。成因不难推：开盘是集合竞价定下的起跑线，收盘是终局，收盘在开盘之上，说明买方把价格从起跑线抬高了，当天买方占上风；反之卖方占优。颜色回答的只有一个问题：这一天，谁赢了。</p><p>它刻意不回答的是：明天谁赢。剧情 60 根蜡烛里有 29 根阳线，其中 8 根的次日收跌——「今天收阳、明天接着涨」这句话，平均每四根阳线里就要落空一次。当天的输赢是真的，次日的剧本是另一天的事。</p><h3 id="上影线与下影线-到达过-没守住" tabindex="-1">上影线与下影线：到达过，没守住 <a class="header-anchor" href="#上影线与下影线-到达过-没守住" aria-label="Permalink to &quot;上影线与下影线：到达过，没守住&quot;">​</a></h3><p>上影线与下影线——实体上方与下方的细线，记录价格一度到达、却没能守住的最高点与最低点。成因仍在连续竞价的拉锯里：冲上去被卖单压回来的路径画成上影，砸下去被买单接住的路径画成下影。影线是攻防的未遂记录：到达过，不算数。</p><p>用剧情里最有戏的两根来演算。D19：开盘 11.12，盘中最高冲到 11.64，比开盘高 4.7%，收盘却只有 11.14——实体 0.02 元，上影 0.50 元。此前 D12 到 D19 连着 8 根阳线把价格推上台阶，这一天有人往上打了最后一炮，被埋伏在高位的卖单整个接走。D30：开盘 9.87，盘中最低探到 9.36，比开盘低 5.2%，收盘拉回 9.91——下影 0.51 元，往下砸的卖单当天就被买盘照单全收。</p><p>影线还解一个常见误会：「影线越长越危险」。长短只是幅度，含义取决于位置。同样一根长上影，出现在连涨之后的高位是卖压现身；出现在长期阴跌之后的低位，多半只是弱反弹遇到抛压。长短给你幅度，位置给你故事。</p><h3 id="成交量-价格运动的燃料" tabindex="-1">成交量：价格运动的燃料 <a class="header-anchor" href="#成交量-价格运动的燃料" aria-label="Permalink to &quot;成交量：价格运动的燃料&quot;">​</a></h3><p>成交量——一个周期内成交的股数，行情软件按「手」计，1 手 = 100 股。为什么需要这个维度？因为价格不会自己动：每一分变动都要由真实成交打出来，而每一笔成交都是一次股权换手（第 2 章）。同样的涨幅，用十倍的换手推出来，和几乎没有换手漂上去，是完全不同的两种行情——不记录成交股数，这两种行情在图上长得一模一样。</p><p>演算就摆在开篇那对蜡烛上。全剧日成交量的中位数约 7.2 万手；D36 放量大阳，27.9 万手，约为中位数的 3.9 倍，是全剧量能最大的一天——买方用真金白银堆出突破。D37 缩量大阳，2.7 万手，只有中位数的 0.38 倍——价格上浮更多是因为没人卖，而不是很多人抢着买。顺带一提，量柱的每一格都是真实成交过的股票，每笔成交都付佣金，卖出还要缴印花税、付过户费（第 3 章）——量越大，市场交的过路费越多。</p><h3 id="一根蜡烛的读法-三步" tabindex="-1">一根蜡烛的读法：三步 <a class="header-anchor" href="#一根蜡烛的读法-三步" aria-label="Permalink to &quot;一根蜡烛的读法：三步&quot;">​</a></h3><p><strong>先看颜色定输赢，再量实体看力量，后看影线找转折。</strong> 颜色回答当天谁赢；实体越长，一边倒得越彻底；影线指出哪一方进攻未遂。最后低头看一眼底下的量柱，问一句：这天是真枪实弹，还是空巷散步？四价、二线、一量，一根蜡烛的全部情报就这些。</p><h2 id="演练-把-40-根蜡烛读一遍" tabindex="-1">演练：把 40 根蜡烛读一遍 <a class="header-anchor" href="#演练-把-40-根蜡烛读一遍" aria-label="Permalink to &quot;演练：把 40 根蜡烛读一遍&quot;">​</a></h2><p>先上工具。下面的交互图由课程组件渲染，数据来自课程导出文件 docs/assets/data/kline-demo.json——固定种子生成的剧情行情，与任何真实个股无关；在课程根目录运行一条命令 pnpm export 就能重新导出，连跑两次逐字节一致。组件只消费这份导出数据，没有第二套手抄的行情；图注与本节同一句口径：教学示意·课程自产合成数据。</p>',23)),n(l),a[1]||(a[1]=e('<p>图分上下两层：上层是蜡烛，下层是逐日对齐的量柱。默认只渲染前 40 根（D1 到 D40），后 20 根暂不上图——先用可见的行情练眼力。把鼠标悬到任何一根蜡烛上，会弹出一张卡片，列出当天的四价与成交量，这是本章的读数仪。</p><p>带着三步读法过一遍剧情：</p><ul><li>D1 到 D12，横盘。价格围着 10 元打转，量柱高矮参差，谁也占不到便宜。</li><li>D12 到 D19，连着 8 根阳线，收盘价从 10.14 一路推到 11.14，量柱温和放大。悬停 D19：上影 0.50 元、实体只有 0.02 元——冲高被压回，攻势到此为止。</li><li>D20 到 D29，连着 10 根阴线，收盘价一路退回 9.9 一带。悬停 D30：下影 0.51 元——砸下去的单子当天被接住，跌势止住。</li><li>D31 到 D35，横盘休整，量柱多在平日水平之下。</li><li>D36，放量大阳：开 10.33、收 10.76，较昨收涨 4.67%，量 27.9 万手，全剧量能之最。</li><li>D37，缩量大阳：开 10.82、收 11.26，同样涨 4.65%，量却只有 2.7 万手。</li><li>D38 到 D40，两根犹豫的小阳加一根缩量小阴，收盘停在 11.43。图到这里切断。</li></ul><p>现在回到开篇那对蜡烛：故事读出来了。D36 是买方真金白银的集结冲锋，D37 是趁无人抛售的顺势上浮——两个故事对后市的暗示相反：放量更可信，缩量存疑。哪个应验？先别翻答案，下一节由你来判。</p><h2 id="验证-先猜-再揭晓" tabindex="-1">验证：先猜，再揭晓 <a class="header-anchor" href="#验证-先猜-再揭晓" aria-label="Permalink to &quot;验证：先猜，再揭晓&quot;">​</a></h2><p>清单里的每个数字都能在图上与导出文件里逐分核对（docs/assets/data/kline-demo.json）。</p><ul><li>[ ] 悬停 D37 的蜡烛，应看到卡片给出四价与量：开 10.82、收 11.26、高 11.31、低 10.77、量约 2.7 万手。口算核验：收减开等于 0.44 元（实体），高减收等于 0.05 元（上影），开减低等于 0.05 元（下影）。</li><li>[ ] 在纸上写下你对后 20 根（D41 到 D60）的判断：A 继续大涨创新高、B 冲高回落涨势夭折、C 就地横盘——结果是三选一，不容弃权；再附一条量能证据，例如「D38 到 D40 量柱一路缩到 2.4 万手，上攻没有部队跟进」。</li><li>[ ] 点击图下方「揭晓后 20 根（D41–D60）」按钮，应看到整图重排为 60 根，D41 到 D60 依次排开。</li><li>[ ] 对照揭晓段与你的猜测：应看到 D44 冲出全剧最高收盘 11.64 后折返，一路回落；D53 放出约平日 2 倍的量、收出 0.59 元的长下影，盘中最低 9.80，比峰值收盘低 15.8%；D60 收在 10.23。你纸上写的是 B 吗？若选了 A 或 C，回看 D38 到 D40 的量柱——连续缩量，答案早写在量里。</li><li>[ ] 定向破坏：把「阳线 = 收盘价高于开盘价」这条判定拆掉，换成「收盘价只要高于昨收就算阳线」，再悬停 D31 读数：开 10.09、收 10.04、昨收 9.91。先落纸预言新规则下 D31 的颜色，再看图——应看到 D31 是绿的（收 10.04 低于开 10.09），而新规则会把它读成红的（10.04 高于 9.91）。两条规则在同一根蜡烛上给出相反颜色，必有一条错，错的是新规则：阳线与阴线锚定的是当天之内买方与卖方的胜负，隔日涨跌是收益率要管的事（第 1 章）。把原判定装回去，D36 的红与 D31 的绿各归其位，图上一根都不用改。</li></ul><p>破坏点选在 D31，因为它是可见区里最容易踩坑的一根：高开 1.8%，收盘比昨收高，却低于开盘——两条规则的分歧在它身上放到最大。猜后揭晓的对照也划清了量价线索的边界：D36 的放量大阳当天买方完胜是真的，可它也没能挡住之后的回落。<strong>单根蜡烛回答的是当天谁占上风，不回答明天涨不涨</strong>；量能提高的是判断的质量，不是确定性。</p><h2 id="收束-回到那对双胞胎蜡烛" tabindex="-1">收束：回到那对双胞胎蜡烛 <a class="header-anchor" href="#收束-回到那对双胞胎蜡烛" aria-label="Permalink to &quot;收束：回到那对双胞胎蜡烛&quot;">​</a></h2><p>回到开篇那对双胞胎，判词可以下了。蜡烛只记录作价的结果，量柱记录作价的方式：D36 那天 27.9 万手换手，说明买方是真金白银冲着拿下这一天来的；D37 那天 2.7 万手，说明上涨几乎没花力气——没有抛压，也没有新买盘。揭晓段站在缩量这边：D37 之后量能再没起来，价格在 11.64 见顶折返，D53 靠一根放量长下影才止住，D60 收 10.23。两个故事对当天的描述都对，对后市的暗示却分了高下——存疑的那个应验了。</p><p>这一章新增四块积木：K线、阳线与阴线、上影线与下影线、成交量——蜡烛管四价、颜色管输赢、影线管未遂、量柱管代价，完整定义与接口进了附录「术语表」。两个最容易翻车的地方，各配一个数：阳线不代表第二天还会涨，全剧 29 根阳线里 8 根次日收跌；影线不分长短定凶险，低位长下影是承接，高位长上影是卖压。还有两句边界：蜡烛量不出公司的分量，称公司要用市值、盈利与估值（第 2 章）；单日 4.65% 的日子一个月碰不上几回，指望它按复利月月滚是幻想，这点涨幅最终剩下多少实际购买力，还要过通货膨胀那一关（第 1 章）。</p><p>一根蜡烛管一天。把几十根蜡烛的收盘价连成线看方向，是均线与趋势的课题（第 5 章）——那是判断故事会不会延续的工具，本章先管好当天谁赢。</p><h3 id="自查-换一根蜡烛-还会读吗" tabindex="-1">自查：换一根蜡烛，还会读吗 <a class="header-anchor" href="#自查-换一根蜡烛-还会读吗" aria-label="Permalink to &quot;自查：换一根蜡烛，还会读吗&quot;">​</a></h3><ol><li>一根蜡烛四价：开 9.90、收 10.12、高 10.15、低 9.85。颜色、实体、上影、下影各是多少？这天谁占上风？</li><li>某天行情过热，开盘即封死涨停 11.00 元（前收盘 10.00，按主板 ±10%），全天所有成交都发生在 11.00。这根蜡烛画出来长什么样？</li><li>同样是 0.5 元的上影线：一根出现在连涨 8 天之后，一根出现在连跌 10 天之后。各自读出什么？</li><li>连跌途中的某天放出平日 5 倍的量，收出一根带长下影的小阳线。用本章的词把这一天的画面描述一遍；它能证明跌势已经反转吗？</li><li>你在 D36 收盘前买入，最早哪天能卖？若 D37 一开盘就封死涨停，你的卖出委托会怎样？封的是跌停呢？</li></ol><details><summary>自查答案</summary><ol><li>收 10.12 高于开 9.90，阳线（红）；实体 0.22 元；上影 10.15 − 10.12 = 0.03 元；下影 9.90 − 9.85 = 0.05 元。实体明显长于两条影线，买方当天占优。</li><li>开、收、高、低全是 11.00：实体高度为零（收高于开，按阳线着色），上下影都没有，图上是一根短横线，行情软件里叫一字线。涨跌停板把全天价格钉在同一个价位，四价被压成一价。</li><li>连涨之后的长上影读作卖压现身、冲高受阻；连跌之后的长上影多半只是弱反弹遭遇抛压，弱势未改。长短只给出幅度，位置才给出故事——解读影线先看它在行情的哪一段。</li><li>画面：低位、换手急剧放大、盘中深跌又被拉回、收小阳——抛单被买方照单全收，是有承接的信号，与揭晓段 D53 那根同类。但一天的证据证明不了反转：它说明当天砸盘的力量被消化，方向确认还要看后面的蜡烛与量能不能跟上。</li><li>D36 买入，最早 D37 卖出。封涨停时想买的排长队、卖单稀少，你的卖出委托按涨停价立即成交；封跌停时相反，卖出的人排长队，你的卖单可能到收盘都无法成交。T+1 决定你能不能卖，涨跌停板决定哪个价位有对手盘。</li></ol></details><p>到这一章，进场篇的行情语言你已入门：会算规则与成本（第 3 章），会读一天的多空（本章）。本章行情全部为教学示意·课程自产合成数据，与任何真实个股无关，不构成任何投资建议。</p>',16))])}const b=i(s,[["render",h]]);export{m as __pageData,b as default};
